const LEGEND_EN: &str = " \\* Background for people: where this constitution comes from, how it is organized and how it is amended. The agent version, `constitution/2026-10/generated/constitution.en.agent.md`, omits these parts.";
const LEGEND_ZH: &str = "\\* 写给人看的背景：本宪法的由来、结构和修改方式。agent 版 `constitution/2026-10/generated/constitution.zh.agent.md` 不收录这些部分。";
const STAR: &str = "<sup class=\"omitted\">*</sup>";

const IDX: &str = "constitution/2026-10/index.toml";
const A: &str = "constitution/2026-10/articles/01-alpha";
const B: &str = "constitution/2026-10/articles/02-beta";

fn sections() -> [String; 3] {
    [
        format!("{A}/01-alpha-one.toml"),
        format!("{B}/01-beta-one.toml"),
        format!("{B}/01a-beta-two.toml"),
    ]
}

/// A valid source tree in a directory of its own, edited per test.
struct Tree {
    root: PathBuf,
}

impl Tree {
    fn new(name: &str) -> Tree {
        let root = Path::new(env!("CARGO_TARGET_TMPDIR"))
            .join("constitution")
            .join(name);
        let _ = std::fs::remove_dir_all(&root);
        let tree = Tree { root };
        tree.write(IDX, INDEX);
        tree.write(&format!("{A}/article.toml"), ALPHA);
        tree.write(&format!("{A}/01-alpha-one.toml"), ALPHA_ONE);
        tree.write(&format!("{B}/article.toml"), BETA);
        tree.write(&format!("{B}/01-beta-one.toml"), BETA_ONE);
        tree.write(&format!("{B}/01a-beta-two.toml"), BETA_TWO);
        tree
    }

    fn write(&self, name: &str, text: &str) {
        let path = self.root.join(name);
        std::fs::create_dir_all(path.parent().unwrap()).unwrap();
        std::fs::write(path, text).unwrap();
    }

    fn read(&self, name: &str) -> String {
        std::fs::read_to_string(self.root.join(name)).unwrap()
    }

    /// Replaces `old` with `new` in the file, `count` times, or every time
    /// with `None`; `old` must be there.
    fn edit_n(&self, name: &str, old: &str, new: &str, count: Option<usize>) {
        let text = self.read(name);
        assert!(text.contains(old), "{name} lacks {old:?}");
        let text = match count {
            Some(n) => text.replacen(old, new, n),
            None => text.replace(old, new),
        };
        self.write(name, &text);
    }

    fn edit(&self, name: &str, old: &str, new: &str) {
        self.edit_n(name, old, new, Some(1));
    }

    fn rename(&self, old: &str, new: &str) {
        let new = self.root.join(new);
        std::fs::create_dir_all(new.parent().unwrap()).unwrap();
        std::fs::rename(self.root.join(old), new).unwrap();
    }

    fn remove(&self, name: &str) {
        std::fs::remove_file(self.root.join(name)).unwrap();
    }

    /// Makes the tree active: the index and the sections and items.
    fn activate(&self) {
        self.edit(IDX, "status = \"draft\"", "status = \"active\"");
        self.edit(IDX, "revision = \"0.2\"", "revision = \"1\"");
        for name in sections() {
            self.edit_n(&name, "status = \"draft\"", "status = \"active\"", None);
        }
    }

    fn errors(&self) -> Vec<String> {
        build(&self.root).err().unwrap_or_default().0
    }

    fn outputs(&self) -> Outputs {
        match build(&self.root) {
            Ok((_, outputs)) => outputs,
            Err(e) => panic!("{:?}", e.0),
        }
    }

    /// Asserts that the build fails with errors of check `check` only,
    /// among them `<location>: check <check>: <message>`.
    fn assert_fails(&self, check: u8, location: &str, message: &str) {
        let errors = self.errors();
        assert!(!errors.is_empty(), "expected an error, got none");
        let tag = format!(": check {check}: ");
        assert!(errors.iter().all(|e| e.contains(&tag)), "{errors:?}");
        let want = format!("{location}{tag}{message}");
        assert!(errors.contains(&want), "{want:?} not in {errors:?}");
    }

    /// Runs statute with `args` on the tree; its exit status and stderr.
    fn statute(&self, args: &[&str]) -> (i32, String, String) {
        let out = Command::new(env!("CARGO_BIN_EXE_statute"))
            .args(["constitution", "build", "--root"])
            .arg(&self.root)
            .args(args)
            .output()
            .unwrap();
        (
            out.status.code().unwrap(),
            String::from_utf8(out.stdout).unwrap(),
            String::from_utf8(out.stderr).unwrap(),
        )
    }

    fn git(&self, args: &[&str]) {
        git(&self.root, args);
    }

    /// Writes the outputs and commits the tree as the base, `HEAD`,
    /// active unless `active` is false.
    fn commit_base(&self, active: bool) {
        if active {
            self.activate();
        }
        assert_eq!(self.statute(&[]).0, 0);
        self.git(&["init", "-q"]);
        self.git(&["add", "-A"]);
        self.git(&["commit", "-q", "-m", "base"]);
    }

    /// The numbering part of check 7 against `HEAD`: the errors and the
    /// note.
    fn base_errors(&self) -> (Vec<String>, Option<String>) {
        let (src, _) = build(&self.root).unwrap();
        let mut errors = Errors::default();
        let note = base::check_numbering(&self.root, "HEAD", &src, &mut errors).unwrap();
        (errors.0, note)
    }

    /// The revision part of check 7 against `HEAD`.
    fn revision_check(&self) -> Vec<String> {
        let (src, _) = build(&self.root).unwrap();
        let mut errors = Errors::default();
        base::check_revision(&self.root, "HEAD", &src, &mut errors).unwrap();
        errors.0
    }
}

fn output(outputs: &Outputs, name: &str) -> String {
    outputs
        .iter()
        .find(|(n, _)| n == name)
        .map(|(_, t)| t.clone())
        .unwrap()
}

fn git(dir: &Path, args: &[&str]) {
    let out = Command::new("git")
        .arg("-C")
        .arg(dir)
        .args([
            "-c",
            "user.name=Test",
            "-c",
            "user.email=test@example.test",
            "-c",
            "maintenance.auto=false",
            "-c",
            "commit.gpgsign=false",
        ])
        .args(args)
        .env_remove("GIT_DIR")
        .env_remove("GIT_INDEX_FILE")
        .env_remove("GIT_WORK_TREE")
        .output()
        .unwrap();
    assert!(
        out.status.success(),
        "git {args:?}: {}",
        String::from_utf8_lossy(&out.stderr)
    );
}

/// The text without anchors, bold and link markup.
fn plain(text: &str) -> String {
    let text = Regex::new(r#"<a id="[^"]+"></a>"#)
        .unwrap()
        .replace_all(text, "")
        .replace("**", "");
    Regex::new(r"\[([^\]]+)\]\[[^\]]+\]")
        .unwrap()
        .replace_all(&text, "$1")
        .into_owned()
}

// The repository's own edition.

#[test]
fn this_repository_builds_to_its_generated_files() {
    let root = Path::new(env!("CARGO_MANIFEST_DIR")).join("../..");
    let (src, outputs) = build(&root).unwrap_or_else(|e| panic!("{:?}", e.0));
    assert_eq!(outputs.len(), 2 * src.languages.len());
    for (name, text) in &outputs {
        let path = root.join(src.layout.output(name));
        let committed = std::fs::read(&path).unwrap();
        assert!(
            committed == text.as_bytes(),
            "{} differs from the build",
            path.display()
        );
    }
}

/// The labels of the build are those `cite::Labels` reads for a rule's
/// citations, for every provision of this repository's edition.
#[test]
fn this_repositorys_labels_match_cite_labels() {
    let root = Path::new(env!("CARGO_MANIFEST_DIR")).join("../..");
    let (src, _) = build(&root).unwrap_or_else(|e| panic!("{:?}", e.0));
    assert!(!src.provisions().is_empty());
    for lang in &src.languages {
        let built = statute::constitution::labels(lang, &src);
        let cited = statute::cite::Labels::load(&root.join(src.layout.articles()), lang).unwrap();
        let cited: std::collections::BTreeMap<String, String> = cited
            .iter()
            .map(|(id, label)| (id.to_string(), label.to_string()))
            .collect();
        assert_eq!(built, cited, "{lang}");
        assert_eq!(
            built
                .keys()
                .cloned()
                .collect::<std::collections::BTreeSet<_>>(),
            src.provisions()
        );
    }
}

// Rendering.

#[test]
fn valid_tree_renders_both_languages() {
    let t = Tree::new("renders");
    let outputs = t.outputs();
    let names: Vec<&str> = outputs.iter().map(|(n, _)| n.as_str()).collect();
    assert_eq!(names, ["en", "zh", "en.agent", "zh.agent"]);
    assert_eq!(output(&outputs, "en"), EN);
    assert_eq!(output(&outputs, "zh"), ZH);
    assert_eq!(output(&outputs, "en.agent"), EN_AGENT);
    assert_eq!(output(&outputs, "zh.agent"), ZH_AGENT);
}

#[test]
fn write_then_check() {
    let t = Tree::new("write-then-check");
    assert_eq!(t.statute(&[]).0, 0);
    assert_eq!(
        t.read("constitution/2026-10/generated/constitution.zh.md"),
        ZH
    );
    assert_eq!(
        t.read("constitution/2026-10/generated/constitution.zh.agent.md"),
        ZH_AGENT
    );
    assert_eq!(t.statute(&["--check"]).0, 0);
}

#[test]
fn preamble_heading_is_marked() {
    let t = Tree::new("preamble-heading");
    t.edit(
        IDX,
        "The preamble cites",
        "## Preamble\n\nThe preamble cites",
    );
    t.edit(IDX, "序言引用{@beta}", "## 序言\n\n序言引用{@beta}");
    let outputs = t.outputs();
    assert!(output(&outputs, "en").contains(&format!("\n## Preamble{STAR}\n\nThe preamble cites")));
    assert!(output(&outputs, "zh").contains(&format!("\n## 序言{STAR}\n\n序言引用")));
    for (lang, legend) in [("en", LEGEND_EN), ("zh", LEGEND_ZH)] {
        assert!(output(&outputs, lang).contains(&format!("{legend}\n")));
        assert!(!output(&outputs, &format!("{lang}.agent")).contains(STAR));
    }
}

#[test]
fn provisions_for_maintainers() {
    let t = Tree::new("maintainers");
    t.edit(
        &format!("{B}/01a-beta-two.toml"),
        "status = \"draft\"",
        "status = \"draft\"\naudience = \"maintainers\"",
    );
    t.edit(
        &format!("{A}/01-alpha-one.toml"),
        "number = \"2\"\nstatus = \"draft\"",
        "number = \"2\"\nstatus = \"draft\"\naudience = \"maintainers\"",
    );
    let outputs = t.outputs();
    let (en, zh) = (output(&outputs, "en"), output(&outputs, "zh"));
    assert!(en.contains(&format!(
        "\n-   <a id=\"beta-two\"></a>**§1a**{STAR} Between:\n"
    )));
    assert!(en.contains(&format!(
        "\n    -   <a id=\"alpha-one.machines\"></a>(**2**){STAR} Machines;"
    )));
    assert!(zh.contains(&format!(
        "\n-   <a id=\"beta-two\"></a>**第一款之一**{STAR} 之间：\n"
    )));
    assert!(zh.contains(&format!(
        "\n    -   <a id=\"alpha-one.machines\"></a>(**二**){STAR} 机器；"
    )));
    assert!(en.contains(&format!("Language: English.{LEGEND_EN}\n")));
    assert!(zh.contains(&format!("语言：中文。{LEGEND_ZH}\n")));
    assert_eq!(en.replace(STAR, "").replace(LEGEND_EN, ""), EN);
    assert_eq!(zh.replace(STAR, "").replace(LEGEND_ZH, ""), ZH);
    assert_eq!(
        output(&outputs, "en.agent"),
        EN_AGENT
            .replace(
                "    -   (**2**) Machines; {braces} and {@Nope} stay.\n        More.\n",
                "    -   (**2**) (see the full text)\n",
            )
            .replace(
                "-   **§1a** Between:\n    1. first\n\n       more\n    2. second\n",
                "-   **§1a** (see the full text)\n",
            )
    );
    assert_eq!(
        output(&outputs, "zh.agent"),
        ZH_AGENT
            .replace(
                "    -   (**二**) 机器；{braces} 与 {@Nope} 不变。\n        更多。\n",
                "    -   (**二**) (见完整版)\n",
            )
            .replace(
                "-   **第一款之一** 之间：\n    1. 第一\n\n       更多\n    2. 第二\n",
                "-   **第一款之一** (见完整版)\n",
            )
    );
}

#[test]
fn repealed_placeholders() {
    let t = Tree::new("repealed");
    t.activate();
    t.edit(
        &format!("{B}/01-beta-one.toml"),
        "status = \"active\"",
        "status = \"repealed\"\nrepealed = \"2026-11\"",
    );
    t.edit(
        &format!("{A}/01-alpha-one.toml"),
        "number = \"2\"\nstatus = \"active\"",
        "number = \"2\"\nstatus = \"repealed\"\nrepealed = \"2026-11\"",
    );
    t.write(
        "constitution/2026-10/articles/03-gamma/article.toml",
        &BETA
            .replace("\"beta\"", "\"gamma\"")
            .replace("[title]", "repealed = \"2026-12\"\n\n[title]"),
    );
    // A citation of a repealed section would be an error; move it.
    t.edit_n(
        &format!("{A}/01-alpha-one.toml"),
        "{@beta-one}",
        "{@beta-two}",
        Some(2),
    );
    let outputs = t.outputs();
    let (en, zh) = (output(&outputs, "en"), output(&outputs, "zh"));
    assert!(
        en.contains(
            "\n    -   <a id=\"alpha-one.machines\"></a>(**2**) (repealed November 2026)\n"
        )
    );
    assert!(en.contains("\n-   <a id=\"beta-one\"></a>**§1** (repealed November 2026)\n"));
    assert!(en.contains("\n## <a id=\"gamma\"></a>Article III (repealed December 2026)\n\n["));
    assert!(
        zh.contains("\n    -   <a id=\"alpha-one.machines\"></a>(**二**) (2026 年 11 月废止)\n")
    );
    assert!(zh.contains("\n-   <a id=\"beta-one\"></a>**第一款** (2026 年 11 月废止)\n"));
    assert!(zh.contains("\n## <a id=\"gamma\"></a>第三条 (2026 年 12 月废止)\n\n["));
}

#[test]
fn inserted_item() {
    let t = Tree::new("inserted-item");
    t.edit(
        &format!("{A}/01-alpha-one.toml"),
        "id = \"machines\"\nnumber = \"2\"",
        "id = \"machines\"\nnumber = \"1a\"",
    );
    t.edit_n(
        &format!("{B}/01-beta-one.toml"),
        "{@alpha-one.money}",
        "{@alpha-one.machines}",
        Some(2),
    );
    let outputs = t.outputs();
    let (en, zh) = (output(&outputs, "en"), output(&outputs, "zh"));
    assert!(en.contains("\n    -   <a id=\"alpha-one.machines\"></a>(**1a**) Machines;"));
    assert!(en.contains("**§1** Four, see [Art. I §1(1a)][alpha-one.machines] and"));
    assert!(zh.contains("\n    -   <a id=\"alpha-one.machines\"></a>(**一之一**) 机器；"));
    assert!(zh.contains("**第一款** 四，见[第一条第一款第一项之一][alpha-one.machines]和"));
}

/// A section's later paragraphs stay in it and out of the next one: a
/// blank line keeps the next section's line out of its last paragraph.
#[test]
fn section_of_several_paragraphs_before_the_next() {
    let t = Tree::new("several-paragraphs");
    let two = format!("{B}/01a-beta-two.toml");
    t.edit(&two, "2. second\n", "2. second\n\nAfter.\n");
    t.edit(&two, "2. 第二\n", "2. 第二\n\n之后。\n");
    t.write(
        &format!("{B}/02-beta-three.toml"),
        "id = \"beta-three\"\nstatus = \"draft\"\n\n[content]\nen = \"Next.\"\nzh = \"下一款。\"\n",
    );
    let outputs = t.outputs();
    assert!(output(&outputs, "en").contains(
        "**§1a** Between:\n    1. first\n\n       more\n    2. second\n\n    After.\n\n-   <a id=\"beta-three\"></a>**§2** Next.\n"
    ));
    assert!(output(&outputs, "zh").contains(
        "**第一款之一** 之间：\n    1. 第一\n\n       更多\n    2. 第二\n\n    之后。\n\n-   <a id=\"beta-three\"></a>**第二款** 下一款。\n"
    ));
}

