/// The version for agents opens with the build's note on the status: a
/// draft may be used on a trial basis but is not final; once active,
/// every agent must follow it.
#[test]
fn agent_front_follows_the_status() {
    let t = Tree::new("agent-front");
    let draft = t.outputs();
    t.activate();
    let active = t.outputs();
    for (lang, in_draft, in_force) in [
        (
            "en",
            "a draft that may be used on a trial basis but is not final",
            "every agent must follow it",
        ),
        (
            "zh",
            "本宪法现为草案，可以试行，但尚未定稿",
            "每个 agent 都必须遵守它",
        ),
    ] {
        let name = format!("{lang}.agent");
        let (d, a) = (output(&draft, &name), output(&active, &name));
        assert!(d.contains(in_draft) && !d.contains(in_force), "{lang}");
        assert!(a.contains(in_force) && !a.contains(in_draft), "{lang}");
        assert!(!(d.clone() + &a).contains("preamble cites"));
        assert!(!(d + &a).contains("序言引用"));
    }
}

#[test]
fn adjacent_section_citations_render_short() {
    let t = Tree::new("adjacent-sections");
    t.write(
        &format!("{B}/02-beta-three.toml"),
        "id = \"beta-three\"\nstatus = \"draft\"\n\n[content]\nen = \"Three.\"\nzh = \"三。\"\n",
    );
    let cites = [
        ("{@beta-one} and {@beta-two}", "{@beta-one}和{@beta-two}"),
        ("{@beta-one} to {@beta-three}", "{@beta-one}至{@beta-three}"),
        (
            "{@beta-one}, {@beta-two} or {@beta-three}",
            "{@beta-one}、{@beta-two}或{@beta-three}",
        ),
        ("{@alpha-one} and {@beta-one}", "{@alpha-one}和{@beta-one}"),
        (
            "{@beta-one} and then {@beta-two}",
            "{@beta-one}和后来的{@beta-two}",
        ),
        ("{@beta} and {@beta-one}", "{@beta}和{@beta-one}"),
        (
            "{@beta-one} and {@beta-two.x}",
            "{@beta-one}和{@beta-two.x}",
        ),
        (
            "{@alpha-one.money} and {@beta-one}",
            "{@alpha-one.money}和{@beta-one}",
        ),
    ];
    t.edit(
        &format!("{B}/01a-beta-two.toml"),
        "status = \"draft\"",
        "status = \"draft\"\nitems = [{ id = \"x\", number = \"1\", status = \"draft\", content = { en = \"X.\", zh = \"X。\" } }]",
    );
    let en: Vec<String> = cites.iter().map(|(e, _)| format!("Cite {e}.")).collect();
    let zh: Vec<String> = cites.iter().map(|(_, z)| format!("引用{z}。")).collect();
    let one = format!("{A}/01-alpha-one.toml");
    t.edit(&one, "One, see {@beta-one}.", &en.join("\n"));
    t.edit(&one, "一，见{@beta-one}。", &zh.join("\n"));
    let outputs = t.outputs();
    assert!(output(&outputs, "en").contains("Cite [Art. II §1][beta-one] and [§1a][beta-two].\n"));
    assert!(
        output(&outputs, "zh").contains("引用[第二条第一款][beta-one]和[第一款之一][beta-two]。\n")
    );
    assert!(plain(&output(&outputs, "en")).contains(
        "-   §1 Cite Art. II §1 and §1a.\n\
         \x20   Cite Art. II §1 to §2.\n\
         \x20   Cite Art. II §1, §1a or §2.\n\
         \x20   Cite Art. I §1 and Art. II §1.\n\
         \x20   Cite Art. II §1 and then Art. II §1a.\n\
         \x20   Cite Art. II and Art. II §1.\n\
         \x20   Cite Art. II §1 and Art. II §1a(1).\n\
         \x20   Cite Art. I §1(1) and Art. II §1.\n"
    ));
    assert!(plain(&output(&outputs, "zh")).contains(
        "-   第一款 引用第二条第一款和第一款之一。\n\
         \x20   引用第二条第一款至第二款。\n\
         \x20   引用第二条第一款、第一款之一或第二款。\n\
         \x20   引用第一条第一款和第二条第一款。\n\
         \x20   引用第二条第一款和后来的第二条第一款之一。\n\
         \x20   引用第二条和第二条第一款。\n\
         \x20   引用第二条第一款和第二条第一款之一第一项。\n\
         \x20   引用第一条第一款第一项和第二条第一款。\n"
    ));
}

