/// A file the base lists but git cannot read fails check 7.
#[test]
fn check_7_unreadable_base_file() {
    let t = Tree::new("base-unreadable");
    t.commit_base(true);
    let out = Command::new("git")
        .arg("-C")
        .arg(&t.root)
        .args(["rev-parse", &format!("HEAD:{IDX}")])
        .env_remove("GIT_DIR")
        .env_remove("GIT_INDEX_FILE")
        .output()
        .unwrap();
    let blob = String::from_utf8(out.stdout).unwrap().trim().to_string();
    std::fs::remove_file(
        t.root
            .join(".git/objects")
            .join(&blob[..2])
            .join(&blob[2..]),
    )
    .unwrap();
    let (code, _, stderr) = t.statute(&["--check", "--base", "HEAD"]);
    assert_eq!(code, 1);
    assert!(
        stderr.contains(&format!("check 7: `git show HEAD:{IDX}` failed:")),
        "{stderr}"
    );
}

