/// Moves the edition directory to another name, rebuilds and stages it;
/// the new directory.
fn move_edition_dir(t: &Tree) -> String {
    let new = "constitution/2026-11";
    t.rename("constitution/2026-10", new);
    assert_eq!(t.statute(&[]).0, 0);
    t.git(&["add", "-A"]);
    new.to_string()
}

