// Check 7: the revision.

fn change_text(t: &Tree) {
    t.edit(
        &format!("{A}/article.toml"),
        "en = \"First\"",
        "en = \"First one\"",
    );
}

fn set_revision(t: &Tree, old: &str, new: &str) {
    t.edit(
        IDX,
        &format!("revision = \"{old}\""),
        &format!("revision = \"{new}\""),
    );
}

fn not_greater(revision: &str, base: &str) -> Vec<String> {
    vec![format!(
        "{IDX}:3: check 7: the constitution text changed since base HEAD but revision {revision} is not greater than the base's {base}"
    )]
}

#[test]
fn check_7_main_runs_revision_check() {
    let t = Tree::new("revision-main");
    t.commit_base(true);
    change_text(&t);
    assert_eq!(t.statute(&[]).0, 0);
    assert_eq!(t.statute(&["--check", "--base", "HEAD"]).0, 1);
    set_revision(&t, "1", "2");
    assert_eq!(t.statute(&[]).0, 0);
    assert_eq!(t.statute(&["--check", "--base", "HEAD"]).0, 0);
}

#[test]
fn check_7_text_change_and_revision() {
    let t = Tree::new("revision-text-change");
    t.commit_base(true);
    assert_eq!(t.revision_check(), Vec::<String>::new());
    change_text(&t);
    assert_eq!(t.revision_check(), not_greater("1", "1"));
    set_revision(&t, "1", "2");
    assert_eq!(t.revision_check(), Vec::<String>::new());
}

