#[test]
fn draft_revisions_sort_below_whole_numbers() {
    let keys: Vec<_> = ["0.2", "0.9", "0.10", "1", "2", "10"]
        .iter()
        .map(|r| base::revision_key(r).unwrap())
        .collect();
    let mut sorted = keys.clone();
    sorted.sort();
    sorted.dedup();
    assert_eq!(keys, sorted);
    assert_eq!(base::revision_key("0.x"), None);
    assert_eq!(base::revision_key("01"), None);
}

