fn check_7_new_edition_revision_is_not_compared() {
    let t = Tree::new("revision-new-edition");
    t.activate();
    set_revision(&t, "1", "5");
    t.commit_base(false);
    change_text(&t);
    t.edit(IDX, "edition = \"2026-10\"", "edition = \"2027-03\"");
    set_revision(&t, "5", "1");
    assert_eq!(t.revision_check(), Vec::<String>::new());
}

fn name_edition(t: &Tree, edition: &str) {
    let text = Regex::new(r#"edition = ".*"\n"#)
        .unwrap()
        .replace_all(&t.read(IDX), "")
        .into_owned();
    t.write(
        IDX,
        &text.replace(
            "revision =",
            &format!("edition = \"{edition}\"\nrevision ="),
        ),
    );
}

/// Renaming the edition a draft prepares does not restart its revisions.
#[test]
fn check_7_draft_renaming_its_edition_compares_revisions() {
    let t = Tree::new("revision-draft-rename");
    name_edition(&t, "2026-10");
    t.commit_base(false);
    name_edition(&t, "2026-11");
    assert_eq!(t.revision_check(), not_greater("0.2", "0.2"));
    set_revision(&t, "0.2", "0.3");
    assert_eq!(t.revision_check(), Vec::<String>::new());
}

/// The approved text's revision is greater than the draft's.
#[test]
fn check_7_approval_compares_with_the_draft() {
    let t = Tree::new("revision-approval");
    name_edition(&t, "2026-10");
    t.commit_base(false);
    t.edit(IDX, "status = \"draft\"", "status = \"active\"");
    for name in sections() {
        t.edit_n(&name, "status = \"draft\"", "status = \"active\"", None);
    }
    assert_eq!(t.revision_check(), not_greater("0.2", "0.2"));
    set_revision(&t, "0.2", "1");
    assert_eq!(t.revision_check(), Vec::<String>::new());
}

